#include <flint/fmpq.h>
#include <flint/fmpq_mpoly.h>
#include <flint/fmpq_mpoly_factor.h>
#include <fstream>
#include <iostream>
#include <vector>
#include <string>
#include <cassert>
#include <chrono>
using namespace std;fmpq_mpoly_ctx_t ctx;
struct Poly{fmpq_mpoly_t p;Poly(){fmpq_mpoly_init(p,ctx);}Poly(const Poly&a):Poly(){fmpq_mpoly_set(p,a.p,ctx);}Poly(Poly&&a):Poly(){fmpq_mpoly_swap(p,a.p,ctx);}Poly&operator=(Poly a){fmpq_mpoly_swap(p,a.p,ctx);return *this;}~Poly(){fmpq_mpoly_clear(p,ctx);}};
void write(ostream&o,const Poly&a){fmpq_t q;fmpq_init(q);ulong ex[3];int n=fmpq_mpoly_length(a.p,ctx);o<<n;for(int i=0;i<n;i++){fmpq_mpoly_get_term_coeff_fmpq(q,a.p,i,ctx);fmpq_mpoly_get_term_exp_ui(ex,a.p,i,ctx);char*s=fmpq_get_str(nullptr,10,q);o<<' '<<s;for(ulong x:ex)o<<' '<<x;flint_free(s);}o<<'\n';fmpq_clear(q);}
Poly determinant(vector<vector<Poly>> A){Poly prev,x,y,z;fmpq_mpoly_one(prev.p,ctx);int n=A.size(),sign=1;for(int k=0;k<n-1;k++){int bi=-1,bj=-1;long cost=10000000;for(int i=k;i<n;i++)for(int j=k;j<n;j++){int l=fmpq_mpoly_length(A[i][j].p,ctx);if(l&&l<cost){cost=l;bi=i;bj=j;}}assert(bi>=0);if(k!=bi)sign=-sign;if(k!=bj)sign=-sign;swap(A[k],A[bi]);for(auto&r:A)swap(r[k],r[bj]);for(int i=k+1;i<n;i++)for(int j=k+1;j<n;j++){fmpq_mpoly_mul(x.p,A[k][k].p,A[i][j].p,ctx);fmpq_mpoly_mul(y.p,A[i][k].p,A[k][j].p,ctx);fmpq_mpoly_sub(z.p,x.p,y.p,ctx);assert(fmpq_mpoly_divides(A[i][j].p,z.p,prev.p,ctx));}prev=A[k][k];}Poly answer=A[n-1][n-1];if(sign<0)fmpq_mpoly_neg(answer.p,answer.p,ctx);return answer;}
int main(int argc,char**argv){assert(argc==3);fmpq_mpoly_ctx_init(ctx,3,ORD_LEX);{ifstream in(argv[1]);ofstream out(argv[2]);assert(in.is_open()&&out.is_open());int n,m;in>>n>>m;assert(m==12);vector<vector<Poly>>A(n,vector<Poly>(m));fmpq_t q;fmpq_init(q);ulong ex[3];for(auto&r:A)for(auto&a:r){int l;in>>l;for(int k=0;k<l;k++){string s;in>>s>>ex[0]>>ex[1]>>ex[2];assert(!fmpq_set_str(q,s.c_str(),10));fmpq_canonicalise(q);fmpq_mpoly_push_term_fmpq_ui(a.p,q,ex,ctx);}fmpq_mpoly_sort_terms(a.p,ctx);fmpq_mpoly_combine_like_terms(a.p,ctx);}int count;in>>count;Poly g,gg;auto start=chrono::steady_clock::now();for(int t=0;t<count;t++){vector<int>ids(m);for(int&i:ids)in>>i;vector<vector<Poly>>B;for(int i:ids)B.push_back(A[i]);Poly det=determinant(B);assert(!fmpq_mpoly_is_zero(det.p,ctx));out<<"MINOR "<<t;for(int i:ids)out<<' '<<i;out<<'\n';write(out,det);assert(fmpq_mpoly_gcd(gg.p,g.p,det.p,ctx));g=gg;out<<"GCD "<<t<<'\n';write(out,g);out.flush();assert(out.good());cerr<<"MINOR "<<t<<" DET_TERMS "<<fmpq_mpoly_length(det.p,ctx)<<" GCD_TERMS "<<fmpq_mpoly_length(g.p,ctx)<<" SEC "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';assert(chrono::duration<double>(chrono::steady_clock::now()-start).count()<100);}
fmpq_mpoly_factor_t fac;fmpq_mpoly_factor_init(fac,ctx);assert(fmpq_mpoly_factor(fac,g.p,ctx));out<<"FACTORS "<<fmpq_mpoly_factor_length(fac,ctx)<<'\n';for(int i=0;i<fmpq_mpoly_factor_length(fac,ctx);i++){Poly f;fmpq_mpoly_factor_get_base(f.p,fac,i,ctx);out<<"EXP "<<fmpq_mpoly_factor_get_exp_si(fac,i,ctx)<<'\n';write(out,f);}out.flush();assert(out.good());fmpq_mpoly_factor_clear(fac,ctx);fmpq_clear(q);cerr<<"DONE "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
